const NUM = 6;
let NUMX, NUMY, SZE;
let objs;

function setup() {
	SZE = ~~(max(windowWidth, windowHeight)/NUM);
	NUMX = ~~(windowWidth/SZE);
	NUMY = ~~(windowHeight/SZE);
	createCanvas(NUMX*SZE, NUMX*SZE);

	objs = [];
	for (let y = 0; y < NUMY; y++) {
		for (let x = 0; x < NUMX; x++) {
			let dx = 0, dy = 0, dw = 0, dh = 0;
			if (random() < 0.2) dx = deviateValue(SZE * 0.1);
			if (random() < 0.2) dy = deviateValue(SZE * 0.1);
			if (random() < 0.2) dw = deviateValue(SZE * 0.1);
			if (random() < 0.2) dh = deviateValue(SZE * 0.1);
			objs.push({
				x: x * SZE + dx,
				y: y * SZE + dy,
				w: SZE + dw,
				h: SZE + dh,
				s: random() > 0.1 ? 1 : 2,
				c: random(360)
			})
		}		
	}
	console.log(objs)
}

function deviateValue(d) {
	return random(-d, d);
}

function draw() {
	background(random(360), 128, 96);
	noStroke()
	for (const o of objs) {
		fill(o.c, 128, 128);
		rect(o.x, o.y, o.w * o.s, o.h * o.s);
	}
	// noLoop() removed for animation
}
